<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Staff</title><?= view('partials/styles') ?></head><body><div class="app-shell"><?= view('partials/nav', ['active' => 'users']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Access management</p><h1>Staff accounts</h1><p class="subtitle">Manage staff members who can access your POS system.</p></div><div class="profile"><div class="avatar">AD</div> Admin account</div></header><section class="stat-grid"><div class="stat"><div class="stat-icon">♧</div><div><strong><?= count($users) ?></strong><span>Registered staff</span></div></div><div class="stat"><div class="stat-icon">◈</div><div><strong>Secure</strong><span>Hashed passwords</span></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>Active</strong><span>Account status</span></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Staff directory</h2><span><?= count($users) ?> records found</span></div><a class="button" href="<?= base_url('users/new') ?>">Add staff +</a></div><?php if (session()->getFlashdata('success')): ?><div class="form-error" style="background:#e7faf7;color:#0f9488"><?= esc(session()->getFlashdata('success')) ?></div><?php endif; ?><?php if (session()->getFlashdata('error')): ?><div class="form-error"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?><div class="table-wrap"><table><thead><tr><th>User</th><th>Full name</th><th>Role</th><th>Avatar</th><th>Actions</th></tr></thead><tbody><?php if (!empty($users)): ?><?php foreach ($users as $user): ?><tr><td><div class="person"><span class="person-avatar"><?php if (!empty($user['avatar'])): ?><img class="person-avatar" src="<?= base_url('uploads/avatars/' . $user['avatar']) ?>" alt="Avatar"><?php else: ?><?= esc(strtoupper(substr($user['username'], 0, 1))) ?><?php endif; ?></span><?= esc($user['username']) ?></div></td><td><?= esc($user['full_name']) ?></td><td><span class="badge"><?= esc($user['role'] ?? 'Staff') ?></span></td><td><?= !empty($user['avatar']) ? 'Uploaded' : 'None' ?></td><td><a class="action-link" href="<?= base_url('users/edit/' . $user['id']) ?>">Edit</a><a class="action-link danger" href="<?= base_url('users/delete/' . $user['id']) ?>" onclick="return confirm('Delete this staff account?')">Delete</a></td></tr><?php endforeach; ?><?php else: ?><tr><td colspan="5">No staff accounts found.</td></tr><?php endif; ?></tbody></table></div></section></main></div></body></html>
